import time
import logging
from taf.hw.mcs.exception import (ParameterError, UnknownError, CommandExecuteFailed,
                                  ChannelSetValueFailed, ChannelQueryFailed)


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Command(object):

    def __init__(self, socket_client, device_ip, db_path):
        self._socket_client = socket_client
        self._device_ip = device_ip
        self._db_path = db_path

    def connect(self):
        self._connect_to_device()
        self._connect_to_db()

    def disconnect(self):
        self._disconnect_to_device()

    def _connect_to_device(self):
        command = 'CONNect:DEVIce:{}'.format(self._device_ip)
        result = self._send_command_and_return_response(command)
        self._check_result(result)
        logger.info("connect to device OK")

    def _connect_to_db(self):
        command = 'CONNect:DB:{}'.format(self._db_path)
        result = self._send_command_and_return_response(command)
        self._check_result(result)
        logger.info("Connect to DB OK.")

    def _disconnect_to_device(self):
        command = "DISCONNect:DEVIce:{}".format(self._device_ip)
        result = self._send_command_and_return_response(command)
        self._check_result(result)
        logger.info("disconnect to device OK")

    def set_frequency(self, frequency, timeout=None):
        command = "SET:FREQuency:{}".format(frequency)
        result = self._send_command_and_return_response(command)
        self._check_result(result)
        logger.info("Set frequency OK")
        return result

    def query_frequency(self):
        """
        Command: QUERy:FREQuency
        Response: QUERy:FREQuency:3500_0.25_ALL | 0DB~90DB
        """
        command = "QUERy:FREQuency"
        output = self._send_command_and_return_response(command)
        logger.info("{} ： {}".format(command, output))
        result = output.split("{}:".format(command))[1]
        configured_frequency = result.split("\n")[0].strip()
        logging.info("configured frequency is {}".format(configured_frequency))
        return configured_frequency

    def set_phase(self, channel, phase):
        return self._set_channels_value([channel], [phase], 'SETM:PHASe:')

    def set_phases(self, channels, phases):
        return self._set_channels_value(channels, phases, 'SETM:PHASe:')

    def set_attenuation(self, channel, attenuation):
        return self._set_channels_value([channel], [attenuation], 'SETM:ATT:')

    def set_attenuations(self, channels, attenuations):
        return self._set_channels_value(channels, attenuations, 'SETM:ATT:')

    def _set_channels_value(self, channels, values, cmd_header):
        ret = self._set_channels_value_and_get_response(channels, values, cmd_header)
        if not self._is_command_passed(ret, cmd_header):
            ret = self._set_channels_value_and_get_response(channels, values, cmd_header)
            if not self._is_command_passed(ret, cmd_header):
                result_format = r"Set channel={} value={} with cmd_header={} failed! result={}"
                raise ChannelSetValueFailed(result_format.format(channels, values, cmd_header, ret))
        return ret

    def _set_channels_value_and_get_response(self, channels, values, cmd_header):
        if len(channels) != len(values):
            raise ParameterError("channels number should be equal to values number")

        cmd = ""
        for idx, channel in enumerate(channels):
            cmd = cmd + '{},{:f};'.format(channel, values[idx])
        cmd = cmd_header + cmd

        return self._send_command_and_return_response(cmd.strip(';'))

    @staticmethod
    def _is_command_passed(ret, cmd_header):
        return True if 'OK' in ret.split(cmd_header)[-1] else False

    def get_phase(self, channel):
        phase, _ = self._query_channel_phase_and_attenuation(channel)
        return phase

    def get_attenuation(self, channel):
        _, attenuation = self._query_channel_phase_and_attenuation(channel)
        return attenuation

    def _query_channel_phase_and_attenuation(self, channel):
        cmd = "READm:STATus:{}".format(channel)
        self._socket_client.send_command(cmd.strip(';'))
        except_str = cmd.split(';')[-1]
        ret = self._receive_all_return_value(except_str)
        result = ret.split("READm:STATus:")[-1] + ';'
        if 'FAIL' in result:
            raise ChannelQueryFailed("Query channel's phase and attenuation fail.")

        for info in result.split(";"):
            values = info.split(',')
            if len(values) == 3:
                attenuation, phase = values[1:]
                return [phase.strip(), attenuation.strip()]
        raise ChannelQueryFailed("get channel phase and attenuation failed")

    def get_output_channel_access_right(self, output_channel_id):
        self._send_command_and_return_response("SET:ALLOC:CHANnel:{}".format(output_channel_id))

    def _send_command_and_return_response(self, command):
        logger.info("send mcs command: '{}'".format(command))
        self._socket_client.send_command(command)
        response = self._socket_client.receive_command()
        logger.info("command response: '{}'".format(response))
        return response

    def _send_command_and_wait_for_expected_message(self, command, expected_message, timeout=30):
        logger.info("send mcs command: '{}'".format(command))
        self._socket_client.send_command(command)
        return self._receive_all_return_value(expected_message, timeout=timeout)

    @staticmethod
    def _check_result(result):
        if 'FAIL' in result:
            raise CommandExecuteFailed(result)
        elif 'PARAERR' in result:
            raise ParameterError(result)
        elif 'OK' not in result:
            raise UnknownError(result)
        logger.info("command execute successfully {}".format(result))

    def _receive_all_return_value(self, except_str, timeout=30):
        logger.info("will keep receive return value until '{}' appear.".format(except_str))
        return_value = ""
        while timeout:
            ret = self._socket_client.receive_command()
            return_value = return_value + ret
            if except_str in ret or 'FAIL' in ret:
                break
            timeout = timeout - 1
            time.sleep(1)
        logger.info("receive TopYoung response {}".format(return_value))
        return return_value

    def wait_for_expected_message_received(self, expected_message, timeout=160):
        end_time = time.time() + timeout
        message = ""
        while time.time() < end_time:
            message += self._socket_client.receive_command()
            logger.info("receive {}".format(message))
            if expected_message in message:
                return message
        raise CommandExecuteFailed("wait for {} {}s timeout".format(expected_message, timeout))

    def set_matrix_number(self, number):
        cmd_header = "SET:MATRixnum:"
        command = cmd_header + "{}".format(number)
        output = self._send_command_and_wait_for_expected_message(command, expected_message=cmd_header)
        if 'FAIL' in output:
            logger.error("set matrix number failed, output: {}".format(output))
            return False
        return True

    def read_matrix_number(self):
        command = "READ:MATRixnum"
        output = self._send_command_and_wait_for_expected_message(command, expected_message=command)
        if 'FAIL' in output:
            logger.error("read matrix number failed, output: {}".format(output))
            return None
        """
        output:
            READ:MATRixnum:2
        """
        matrix_number = output.split("{}:".format(command))[-1].strip()
        return int(matrix_number)

    def set_position(self, matrix_positions):
        positions_str = ""
        for matrix_id, positions in matrix_positions.items():
            positions_str += "{}[{}]".format(matrix_id, ';'.join(['{},{},{}'.format(*pos) for pos in positions]))

        cmd_header = "SET:POSItion:"
        command = cmd_header + positions_str
        output = self._send_command_and_wait_for_expected_message(command, expected_message=cmd_header)
        if 'FAIL' in output:
            logger.error("set position failed, output: {}".format(output))
            return False
        return True

    def read_position(self, matrix_positions):
        cmd_header = "READ:POSItion:"
        command = cmd_header + "{}".format(matrix_positions)
        output = self._send_command_and_wait_for_expected_message(command, expected_message=cmd_header)
        if 'FAIL' in output:
            logger.error("read position failed, output: {}".format(output))
            return None
        """
        output:
            READ:POSItion:1[A1,0,0;A2,0,0;A3,0,1;A4,0,1……A63,3,7;A64,3,7]
        """
        output = output.split("{}:".format(command))[-1].strip()
        positions_value = output.split('[')[-1].split(']')[0].split(';')
        positions = []
        for pos in positions_value:
            pos = pos.strip()
            if not pos:
                continue

            items = pos.split(',')
            if len(items) != 3:
                continue

            port, row_number, column_number = items
            positions.append({"port": port, "row_number": int(row_number), "column_number": int(column_number)})
        return positions

    def set_aedis(self, matrix_id,
                  horizontal_d_value, vertical_d_value,
                  ul_horizontal_d_value=None, ul_vertical_d_value=None):
        cmd_header = "SET:AEDIs:"
        if ul_horizontal_d_value is None or ul_vertical_d_value is None:
            command = cmd_header + "{},{},{}".format(matrix_id, horizontal_d_value, vertical_d_value)
        else:
            command = cmd_header + "{},{},{},{},{}".format(
                matrix_id, horizontal_d_value, vertical_d_value, ul_horizontal_d_value, ul_vertical_d_value)
        output = self._send_command_and_wait_for_expected_message(command, expected_message=cmd_header)
        if 'FAIL' in output:
            logger.error("set aedis failed, output: {}".format(output))
            return False
        return True

    def read_aedis(self):
        command = "READ:AEDIs"
        output = self._send_command_and_wait_for_expected_message(command, expected_message=command)
        if 'FAIL' in output:
            logger.error("read aedis failed, output: {}".format(output))
            return None
        """
        output:
            READ:AEDIs:1,0.5,1.4;2,0.5,1.4
        """
        aedis_text = output.split("{}:".format(command))[-1].strip()
        ret = []
        for aedis_item in aedis_text.split(';'):
            aedis_item = aedis_item.strip()
            if not aedis_item:
                continue

            items = aedis_item.split(',')
            if len(items) == 3:
                matrix_id, horizontal_d_value, vertical_d_value = items
                ret.append({"matrix_id": int(matrix_id),
                            "horizontal_d_value": float(horizontal_d_value),
                            "vertical_d_value": float(vertical_d_value)})
            elif len(items) == 5:
                matrix_id, horizontal_d_value, vertical_d_value, ul_horizontal_d_value, ul_vertical_d_value = items
                ret.append({"matrix_id": int(matrix_id),
                            "horizontal_d_value": float(horizontal_d_value),
                            "vertical_d_value": float(vertical_d_value),
                            "ul_horizontal_d_value": float(ul_horizontal_d_value),
                            "ul_vertical_d_value": float(ul_vertical_d_value)})
            else:
                continue

        return ret

    def set_beam(self, port, matrix_id, horizontal_beam_angle, vertical_beam_angle,
                 even_attenuation_enable=False, event_attenuation_value=0,
                 odd_attenuation_enable=False, odd_attenuation_value=0):
        cmd_header = "SET:BEAM:"
        if even_attenuation_enable and odd_attenuation_enable:
            even_attenuation_enable = 1
            odd_attenuation_enable = 1
            command = cmd_header + "{},{},{},{},{},{},{},{}".format(
                port, matrix_id, horizontal_beam_angle, vertical_beam_angle,
                even_attenuation_enable, event_attenuation_value,
                odd_attenuation_enable, odd_attenuation_value)
        else:
            command = cmd_header + "{},{},{},{}".format(
                port, matrix_id, horizontal_beam_angle, vertical_beam_angle)

        logger.info("set beam command: {}".format(command))
        output = self._send_command_and_wait_for_expected_message(command, expected_message=cmd_header)
        if 'FAIL' in output:
            logger.error("set beam failed, output: {}".format(output))
            return False
        return True


class CommandMCS2338A264B16A1(Command):

    def __init__(self, socket_client):
        super(CommandMCS2338A264B16A1, self).__init__(socket_client, None, None)

    def set_frequency(self, frequency, timeout=None):
        timeout = timeout if timeout else 160
        command = "CSN:LOAD:{}".format(frequency)
        self._socket_client.send_command(command)
        return self.wait_for_expected_message_received("CSN:LOAD:OK", timeout=timeout)


class CommandMCS2350A2128B16E6(Command):

    def __init__(self, socket_client):
        super(CommandMCS2350A2128B16E6, self).__init__(socket_client, None, None)

    def set_frequency(self, frequency, timeout=None):
        timeout = timeout if timeout else 6000
        configured_frequency = self.query_frequency()
        if configured_frequency == frequency:
            logger.info("configured frequency is already {}, no action next".format(frequency))
            return
        command = "CSN:LOAD:{}".format(frequency)
        self._socket_client.send_command(command)
        return self.wait_for_expected_message_received("CSN:LOAD:OK", timeout=timeout)

    def _set_channels_value_and_get_response(self, channels, values, cmd_header):
        if len(channels) != len(values):
            raise ParameterError("channels number should be equal to values number")

        cmd = ""
        for idx, channel in enumerate(channels):
            cmd = cmd + '{},{};'.format(channel, int(round(values[idx])))
        cmd = cmd_header + cmd

        return self._send_command_and_return_response(cmd.strip(';'))


class CommandMCS2350A264B16A4(CommandMCS2338A264B16A1):

    def __init__(self, socket_client):
        super(CommandMCS2350A264B16A4, self).__init__(socket_client)

    def set_frequency(self, frequency, timeout=None):
        timeout = timeout if timeout else 160
        command = "CSN:LOAD:{}_1_ALL".format(frequency)
        self._socket_client.send_command(command)
        return self.wait_for_expected_message_received("CSN:LOAD:OK", timeout=timeout)


class CommandMCS2350A2128B16A4(CommandMCS2350A2128B16E6):
    pass


class CommandMCS2350A2128B16A5(CommandMCS2350A2128B16A4):

    def set_frequency(self, frequency, timeout=None):
        timeout = timeout if timeout else 160
        command = "CSN:LOAD:{}".format(frequency)
        self._socket_client.send_command(command)
        return self.wait_for_expected_message_received("CSN:LOAD:OK", timeout=timeout)


class CommandMCS2350A264B16E6(CommandMCS2350A2128B16E6):
    pass


class CommandMCS2350A264B16B1(Command):

    def __init__(self, socket_client):
        super(CommandMCS2350A264B16B1, self).__init__(socket_client, None, None)


class CommandMCS2350A264B32E6(CommandMCS2350A2128B16E6):
    pass


class CommandMCS2350A264B16A5(CommandMCS2350A2128B16E6):

    def __init__(self, socket_client):
        super(CommandMCS2350A264B16A5, self).__init__(socket_client)
